struct GroupInfo {
    int num_patterns;
    int max_len;
    int num_unique_bytes;
    int history_bits;
    bool is_long_group;  // 是否是长patterns组
};

struct PatternRule {
    int original_id;  // 原始rule ID
    int len;          // pattern长度
    unsigned char byte_index[214];  // 索引到该组的unique_bytes
};

