// 辅助宏：获取组信息
#define GET_GROUP_NUM_PATTERNS(g) (group_info[g].num_patterns)
#define GET_GROUP_MAX_LEN(g) (group_info[g].max_len)
#define GET_GROUP_NUM_BYTES(g) (group_info[g].num_unique_bytes)
#define GET_GROUP_HISTORY_BITS(g) (group_info[g].history_bits)
#define IS_LONG_GROUP(g) (group_info[g].is_long_group)

// ========== Testbench辅助函数（仅用于仿真）==========
#ifndef __SYNTHESIS__

inline int get_total_patterns() {
    int total = 0;
    for (int g = 0; g < NUM_GROUPS; g++) {
        total += group_info[g].num_patterns;
    }
    return total;
}

inline bool find_pattern(int original_id, int &group_id, int &local_idx) {
    for (int g = 0; g < NUM_GROUPS; g++) {
        for (int i = 0; i < group_info[g].num_patterns; i++) {
            if (group_rules[g][i].original_id == original_id) {
                group_id = g;
                local_idx = i;
                return true;
            }
        }
    }
    return false;
}

inline int get_pattern_len(int original_id) {
    int g, idx;
    if (find_pattern(original_id, g, idx)) {
        return group_rules[g][idx].len;
    }
    return 0;
}

inline unsigned char get_pattern_byte(int original_id, int byte_pos) {
    int g, idx;
    if (find_pattern(original_id, g, idx)) {
        if (byte_pos < group_rules[g][idx].len) {
            int b_idx = group_rules[g][idx].byte_index[byte_pos];
            return group_bytes[g][b_idx];
        }
    }
    return 0;
}

#endif // __SYNTHESIS__

#endif // PATTERNS_GROUPED_H
